fn wander_world(radius: i32, movement: i32, maps: serde_json::Value) -> ScriptWorld {
    use cyrus_assets::animation::Animations;
    let mut scripts = cache();
    scripts.definition.functions.extend([
        Function {
            name: "MoveByAxis".into(),
            param_count: 3,
            kind: CallKind::Task,
        },
        Function {
            name: "Wander".into(),
            param_count: 2,
            kind: CallKind::Function,
        },
    ]);
    scripts.instances[0].map_position = [1000, 2, 2000];
    let mut operations = Vec::new();
    for (axis, delta) in [(0, movement), (1, 256)] {
        operations.push(wait(
            1,
            "MoveByAxis",
            CallKind::Multitask,
            vec![
                Value::Integer { value: axis },
                Value::Integer { value: delta },
                Value::Integer { value: 1 },
            ],
        ));
    }
    operations.push(Operation::Assign {
        destination: Place::Flag { index: 0 },
        formula: Formula {
            first: Value::Call {
                call: Box::new(Call {
                    function_id: 2,
                    function: "Wander".into(),
                    kind: CallKind::Function,
                    target: Object::Me,
                    arguments: vec![
                        Value::Integer { value: radius },
                        Value::Integer { value: 32768 },
                    ],
                }),
            },
            rest: vec![],
        },
    });
    operations.push(Operation::End { target: 0 });
    scripts.actors.get_mut("LOGIC").unwrap().program.steps = operations
        .into_iter()
        .enumerate()
        .map(|(index, operation)| {
            (
                index as u32,
                Step {
                    next: index as u32 + 1,
                    operation,
                },
            )
        })
        .collect();
    scripts.content_id = scripts.content_identity().unwrap();
    let data = Animations {
        version: 2,
        world: scripts.world,
        metadata: serde_json::json!({"script_content_id": scripts.content_id, "walk_node_maps": maps}),
        sections: Default::default(),
        models: Default::default(),
        unsupported: Default::default(),
    };
    let mut world = ScriptWorld::prepare(&scripts, 1).unwrap();
    world.prepare_navigation(&data).unwrap();
    world.prepare_spatial().unwrap();
    world
}

#[test]
fn empty_map_wander_consumes_original_draws_and_restores_excess_displacement() {
    use cyrus_game::{
        random::EngineRandom,
        script::{ScriptInputs, ScriptStage},
    };
    for (radius, movement, scale, state, restore) in [
        (4, 0, 256, 2524885223, false),
        (5, 0, 256, 3295386429, false),
        (1204, 0, 256, 2524885223, false),
        (1204, 8448, 256, 2524885223, true),
        (1204, 8192, 256, 2524885223, false),
        (1204, 256, 0, 2524885223, true),
    ] {
        let mut world = wander_world(radius * 256, movement, serde_json::json!([]));
        let id = world.id(0).unwrap();
        let mut random = EngineRandom::default();
        world
            .advance(
                id,
                ScriptStage::Body(Thread::Main),
                ScriptInputs {
                    frame_scale: Some(scale),
                    nominal_ticks: Some(0),
                    ..Default::default()
                },
                None,
                Some(&mut random),
                20,
            )
            .unwrap();
        assert_eq!(world.flags(), [movement]);
        assert_eq!(random.state(), state, "radius {radius}");
        assert_eq!(world.actors()[0].attributes()[94], 1);
        assert_eq!(
            world.spatial(id).unwrap().local.position,
            if restore {
                [256000, 512, 512000]
            } else {
                [256000 + movement, 768, 512000]
            }
        );
    }
}

#[test]
fn wander_rejects_a_zero_radius_without_consuming_random() {
    use cyrus_game::{
        random::EngineRandom,
        script::{ScriptInputs, ScriptStage},
    };
    let mut world = wander_world(255, 0, serde_json::json!([]));
    let id = world.id(0).unwrap();
    let mut random = EngineRandom::default();
    let error = world
        .advance(
            id,
            ScriptStage::Body(Thread::Main),
            ScriptInputs {
                frame_scale: Some(256),
                nominal_ticks: Some(0),
                ..Default::default()
            },
            None,
            Some(&mut random),
            20,
        )
        .unwrap_err();
    assert!(
        format!("{error:#}").contains("positive map-unit radius"),
        "{error:#}"
    );
    assert_eq!(random.state(), 1);
    assert!(world.actors()[0].failure().is_some());
}

#[test]
fn wander_with_maps_picks_the_nearest_node_as_its_destination_and_ends_on_arrival() {
    use cyrus_game::{
        random::EngineRandom,
        script::{ScriptInputs, ScriptStage},
    };
    // The home is [1000, 2, 2000] map units; the first map has a node on it, the second none.
    for (maps, found) in [
        (
            serde_json::json!([{"node_count":1,"walk_nodes":[walk_node([1000, 2, 2000])]}]),
            true,
        ),
        (serde_json::json!([{"node_count":0,"walk_nodes":[]}]), false),
    ] {
        let mut world = wander_world(1204 * 256, 0, maps);
        let id = world.id(0).unwrap();
        let mut random = EngineRandom::default();
        world
            .advance(
                id,
                ScriptStage::Body(Thread::Main),
                ScriptInputs {
                    frame_scale: Some(256),
                    nominal_ticks: Some(0),
                    ..Default::default()
                },
                None,
                Some(&mut random),
                20,
            )
            .unwrap();
        assert_eq!(world.actors()[0].attributes()[94], 1);
        assert_eq!(random.state(), 2524885223, "the empty-map draw sequence");
        let navigation = world.actors()[0].control_state().unwrap().navigation;
        // The actor stands on the node, so a found destination is reached and cleared at once.
        assert_eq!(navigation.destination, -1);
        assert_eq!(navigation.map, found.then_some(0));
    }
}

#[test]
fn visibility_calls_return_zero_without_disabling_the_receivers_script() {
    use cyrus_game::script::{ScriptInputs, ScriptStage};
    for (function, hidden) in [("HideMe", true), ("ShowMe", false), ("isDead", false)] {
        let mut scripts = random_scripts(function, vec![], Object::Me);
        scripts.definition.functions[1].param_count = 0;
        scripts.content_id = scripts.content_identity().unwrap();
        let mut world = ScriptWorld::prepare(&scripts, 1).unwrap();
        let id = world.id(0).unwrap();
        for _ in 0..2 {
            world
                .advance(
                    id,
                    ScriptStage::OrdinaryMain,
                    ScriptInputs {
                        frame_scale: Some(256),
                        ..Default::default()
                    },
                    None,
                    None,
                    100,
                )
                .unwrap();
            assert_eq!(world.actors()[0].runtime().unwrap().variables(), [0]);
            let control = world.actors()[0].control_state().unwrap();
            assert_eq!(control.hidden, hidden);
            assert!(!control.object_update_excluded);
            assert_eq!(control.script_control, 0);
            assert!(!world.actors()[1].control_state().unwrap().hidden);
        }
    }
}

#[test]
fn update_player_view_attrib_is_an_empty_call_and_reset_position_keeps_the_home_position() {
    use cyrus_game::script::{ScriptInputs, ScriptStage};
    // updatePlayerViewAttrib is an empty routine in the original: it completes and changes nothing.
    // ResetPosition on an actor already at home leaves it there.
    for (function, arguments, param_count) in [
        ("updatePlayerViewAttrib", vec![], 0),
        (
            "ResetPosition",
            vec![
                Value::Integer { value: 1 },
                Value::Integer { value: 1 },
                Value::Integer { value: 1 },
            ],
            3,
        ),
    ] {
        let mut scripts = random_scripts(function, arguments, Object::Me);
        scripts.definition.functions[1].param_count = param_count;
        if function == "updatePlayerViewAttrib" {
            // Installed scripts call it as a statement: the routine has no numeric result.
            let step = scripts
                .actors
                .get_mut("LOGIC")
                .unwrap()
                .program
                .steps
                .get_mut(&0)
                .unwrap();
            let Operation::Assign { formula, .. } = &step.operation else {
                unreachable!()
            };
            let Value::Call { call } = &formula.first else {
                unreachable!()
            };
            step.operation = Operation::Call {
                call: (**call).clone(),
            };
        }
        scripts.content_id = scripts.content_identity().unwrap();
        let mut world = ScriptWorld::prepare(&scripts, 1).unwrap();
        world.prepare_spatial().unwrap();
        let id = world.id(0).unwrap();
        let before = world.spatial(id).unwrap().local.position;
        world
            .advance(
                id,
                ScriptStage::OrdinaryMain,
                ScriptInputs {
                    frame_scale: Some(256),
                    nominal_ticks: Some(1),
                    ..Default::default()
                },
                None,
                None,
                100,
            )
            .unwrap();
        assert!(world.actors()[0].failure().is_none(), "{function}");
        assert_eq!(
            world.spatial(id).unwrap().local.position,
            before,
            "{function}"
        );
    }
}

