#[test]
fn local_angle_properties_read_and_write_each_axis_without_refreshing_pose() {
    for (axis, name) in ["angle.vx", "angle.vy", "angle.vz"].into_iter().enumerate() {
        let mut scripts = heading_property_scripts(294, Object::Me);
        scripts.definition.references[294] = name.into();
        scripts.instances[0].angles = [100, 1536, 300];
        let step = scripts
            .actors
            .get_mut("LOGIC")
            .unwrap()
            .program
            .steps
            .get_mut(&0)
            .unwrap();
        step.operation = Operation::Assign {
            destination: Place::Property {
                object: Object::Me,
                reference: 294,
            },
            formula: Formula {
                first: Value::Integer { value: 512 },
                rest: vec![],
            },
        };
        scripts.content_id = scripts.content_identity().unwrap();
        let mut world = ScriptWorld::prepare(&scripts, 7).unwrap();
        world.prepare_spatial().unwrap();
        let caller = world.id(0).unwrap();
        let before = world.spatial(caller).unwrap().local;
        world
            .advance(
                caller,
                cyrus_game::script::ScriptStage::Body(Thread::Main),
                cyrus_game::script::ScriptInputs {
                    frame_scale: Some(256),
                    nominal_ticks: Some(1),
                    ..Default::default()
                },
                None,
                None,
                20,
            )
            .unwrap();
        let after = world.spatial(caller).unwrap().local;
        let mut expected = before.angles;
        expected[axis] = 512;
        assert_eq!(after.angles, expected, "{name}");
        assert_eq!(after.position, before.position);
    }
}

#[test]
fn position_properties_read_local_coordinates_without_refreshing_pose() {
    for (axis, name) in ["pos.vx", "pos.vy", "pos.vz"].into_iter().enumerate() {
        for (object, selected) in [
            (Object::Me, false),
            (Object::Player, true),
            (Object::Named { string: 0 }, false),
        ] {
            let mut scripts = heading_property_scripts(294, object);
            scripts.definition.references[294] = name.into();
            scripts.instances[0].map_position = [-7, 11, -13];
            add_standalone_receivers(&mut scripts);
            let mut world = ScriptWorld::prepare(&scripts, 7).unwrap();
            world.prepare_spatial().unwrap();
            let caller = world.id(0).unwrap();
            let player = world.id(2).unwrap();
            world
                .initialize_player_spatial(player, [i32::MIN, -1, i32::MAX], [0; 3])
                .unwrap();
            let receiver = if selected { player } else { caller };
            let before = serde_json::to_value(world.spatial(receiver).unwrap()).unwrap();
            world
                .advance(
                    caller,
                    cyrus_game::script::ScriptStage::Body(Thread::Main),
                    cyrus_game::script::ScriptInputs {
                        frame_scale: Some(256),
                        nominal_ticks: Some(1),
                        ..Default::default()
                    },
                    None,
                    None,
                    20,
                )
                .unwrap();
            let expected = if selected {
                [i32::MIN, -1, i32::MAX][axis]
            } else {
                [-7 * 256, 11 * 256, -13 * 256][axis]
            };
            assert_eq!(world.actors()[0].runtime().unwrap().variables(), [expected]);
            assert_eq!(
                serde_json::to_value(world.spatial(receiver).unwrap()).unwrap(),
                before
            );
        }
    }
}

#[test]
fn position_property_writes_change_only_the_selected_local_coordinate() {
    for (axis, name) in ["pos.vx", "pos.vy", "pos.vz"].into_iter().enumerate() {
        for (object, selected) in [
            (Object::Me, false),
            (Object::Player, true),
            (Object::Named { string: 0 }, false),
        ] {
            for value in [i32::MIN, -1, 0, 1, i32::MAX] {
                let mut scripts = heading_property_scripts(294, object.clone());
                scripts.definition.references[294] = name.into();
                let program = &mut scripts.actors.get_mut("LOGIC").unwrap().program;
                let read = program.steps[&0].operation.clone();
                program.steps.insert(
                    0,
                    Step {
                        next: 1,
                        operation: Operation::Assign {
                            destination: Place::Property {
                                object: object.clone(),
                                reference: 294,
                            },
                            formula: Formula {
                                first: Value::Integer { value },
                                rest: vec![],
                            },
                        },
                    },
                );
                program.steps.insert(
                    1,
                    Step {
                        next: 2,
                        operation: read,
                    },
                );
                program.steps.insert(
                    2,
                    Step {
                        next: 3,
                        operation: Operation::End { target: 0 },
                    },
                );
                add_standalone_receivers(&mut scripts);
                let mut world = ScriptWorld::prepare(&scripts, 7).unwrap();
                world.prepare_spatial().unwrap();
                let caller = world.id(0).unwrap();
                let player = world.id(2).unwrap();
                world
                    .initialize_player_spatial(player, [123, -456, 789], [0; 3])
                    .unwrap();
                let receiver = if selected { player } else { caller };
                let other = if selected { caller } else { player };
                let mut expected = serde_json::to_value(world.spatial(receiver).unwrap()).unwrap();
                expected["local"]["position"][axis] = value.into();
                let other_before = serde_json::to_value(world.spatial(other).unwrap()).unwrap();
                world
                    .advance(
                        caller,
                        cyrus_game::script::ScriptStage::Body(Thread::Main),
                        cyrus_game::script::ScriptInputs {
                            frame_scale: Some(256),
                            nominal_ticks: Some(1),
                            ..Default::default()
                        },
                        None,
                        None,
                        20,
                    )
                    .unwrap();
                assert_eq!(world.actors()[0].runtime().unwrap().variables(), [value]);
                assert_eq!(
                    serde_json::to_value(world.spatial(receiver).unwrap()).unwrap(),
                    expected
                );
                assert_eq!(
                    serde_json::to_value(world.spatial(other).unwrap()).unwrap(),
                    other_before
                );
            }
        }
    }
}

#[test]
fn position_property_access_keeps_attached_effective_pose_until_family_refresh() {
    let mut scripts = heading_property_scripts(294, Object::Me);
    scripts.definition.references[294] = "pos.vx".into();
    let mut child = scripts.actors["LOGIC"].clone();
    child.namespace = Some("child".into());
    child.attributes.insert("attr_26".into(), 1);
    scripts
        .actors
        .get_mut("LOGIC")
        .unwrap()
        .attributes
        .insert("attr_25".into(), 1);
    scripts.actors.insert("CHILD".into(), child);
    scripts.instances[0].map_position = [100, 0, 0];
    scripts.instances[1].map_position = [103, 4, 0];
    scripts.instances[1].actor = "CHILD".into();
    scripts.instances[0].angles = [0; 3];
    let program = &mut scripts.actors.get_mut("CHILD").unwrap().program;
    program.steps.insert(
        1,
        Step {
            next: 2,
            operation: Operation::Assign {
                destination: Place::Property {
                    object: Object::Me,
                    reference: 294,
                },
                formula: Formula {
                    first: Value::Integer { value: -512 },
                    rest: vec![],
                },
            },
        },
    );
    program.steps.insert(
        2,
        Step {
            next: 3,
            operation: Operation::End { target: 0 },
        },
    );
    scripts.content_id = scripts.content_identity().unwrap();
    let mut world = ScriptWorld::prepare(&scripts, 7).unwrap();
    world.prepare_spatial().unwrap();
    world.refresh_families().unwrap();
    let child = world.id(1).unwrap();
    assert_eq!(world.spatial(child).unwrap().local.position[0], 768);
    assert_eq!(
        world.spatial(child).unwrap().effective.unwrap().position[0],
        26368
    );
    let mut expected = serde_json::to_value(world.spatial(child).unwrap()).unwrap();
    expected["local"]["position"][0] = (-512).into();
    world
        .advance(
            child,
            cyrus_game::script::ScriptStage::Body(Thread::Main),
            cyrus_game::script::ScriptInputs {
                frame_scale: Some(256),
                nominal_ticks: Some(1),
                ..Default::default()
            },
            None,
            None,
            20,
        )
        .unwrap();
    assert_eq!(world.actors()[1].runtime().unwrap().variables(), [768]);
    assert_eq!(
        world.model_position(child).unwrap(),
        Some([103.0, 4.0, 0.0])
    );
    assert_eq!(
        serde_json::to_value(world.spatial(child).unwrap()).unwrap(),
        expected
    );
    world.refresh_families().unwrap();
    assert_eq!(
        world.spatial(child).unwrap().effective.unwrap().position[0],
        25088
    );
    assert_eq!(world.model_position(child).unwrap(), Some([98.0, 4.0, 0.0]));
}

fn family_model_fixture(collision: u8) -> (ScriptWorld, cyrus_assets::animation::Animations) {
    let mut scripts = heading_property_scripts(294, Object::Me);
    scripts.definition.references[294] = "pos.vx".into();
    let mut child = scripts.actors["LOGIC"].clone();
    child.attributes.insert("attr_26".into(), 1);
    child.attributes.insert("attr_1".into(), collision);
    scripts
        .actors
        .get_mut("LOGIC")
        .unwrap()
        .attributes
        .insert("attr_25".into(), 1);
    scripts.actors.insert("CHILD".into(), child);
    scripts.instances[1].actor = "CHILD".into();
    scripts.instances[0].angles = [0; 3];
    scripts.instances[1].angles = [0; 3];
    scripts
        .actors
        .get_mut("LOGIC")
        .unwrap()
        .program
        .steps
        .get_mut(&0)
        .unwrap()
        .operation = Operation::Assign {
        destination: Place::Property {
            object: Object::Me,
            reference: 294,
        },
        formula: Formula {
            first: Value::Integer { value: -257 },
            rest: vec![],
        },
    };
    for placement in &mut scripts.instances {
        placement.active = 1;
    }
    let (world, data, _) = static_model_fixture(scripts);
    (world, data)
}

#[test]
fn family_refresh_updates_current_model_without_resampling_geometry_or_root() {
    let (mut world, data) = family_model_fixture(4);
    let root = world.id(0).unwrap();
    let child = world.id(1).unwrap();
    world.set_actor_surface(child, 2).unwrap();
    world.refresh_families().unwrap();
    world
        .refresh_model_presentations(&data, &[root, child])
        .unwrap();
    let before = world.model_presentation(child).unwrap().unwrap();
    let radius = before.radius;
    assert!(before.animation.is_none());
    world
        .advance(
            root,
            cyrus_game::script::ScriptStage::Body(Thread::Main),
            cyrus_game::script::ScriptInputs {
                frame_scale: Some(256),
                nominal_ticks: Some(1),
                ..Default::default()
            },
            None,
            None,
            20,
        )
        .unwrap();
    world.refresh_families().unwrap();
    let current = world.model_presentation(child).unwrap().unwrap();
    assert_eq!(current.position, [-2.0, 20.0, 30.0]);
    assert_eq!(current.pose.position, [-257, 5120, 7680]);
    assert_eq!(
        current.pose.matrix,
        world.spatial(child).unwrap().effective.unwrap().matrix
    );
    assert_eq!(current.radius, radius);
    assert!(current.animation.is_none());
    assert_eq!(world.model_position(child).unwrap(), Some(current.position));
    assert_eq!(
        world.model_presentation(root).unwrap().unwrap().position,
        [10.0, 20.0, 30.0]
    );
}

#[test]
fn automatic_family_models_capture_master_before_ordinary_script_movement() {
    use cyrus_game::script::{OrdinaryInputs, ScriptInputs};
    let (mut world, data) = family_model_fixture(0);
    let root = world.id(0).unwrap();
    let child = world.id(1).unwrap();
    world
        .prepare_model_admission(&Default::default(), 0)
        .unwrap();
    world.refresh_families().unwrap();
    let inputs = ScriptInputs {
        nominal_ticks: Some(1),
        frame_scale: Some(256),
        ..Default::default()
    };
    let mut random = cyrus_game::random::EngineRandom::from_state(42);
    world
        .refresh_automatic_models(
            &data,
            [0; 3],
            None,
            inputs,
            Some(&mut random),
            &mut |_, _| Ok(()),
        )
        .unwrap();
    assert_eq!(
        world.model_position(child).unwrap(),
        Some([10.0, 20.0, 30.0])
    );
    assert_eq!(
        world.model_presentation(child).unwrap().unwrap().position,
        [10.0, 20.0, 30.0]
    );
    world
        .update_ordinary(
            &data,
            [0; 2],
            OrdinaryInputs {
                scripts: inputs,
                scene: None,
            },
            &mut random,
            &mut |_, _| Ok(()),
            100,
        )
        .unwrap();
    assert!(
        world.actors()[root.index].failure().is_none(),
        "{:?}",
        world.actors()[root.index].failure()
    );
    assert_eq!(
        world.spatial(root).unwrap().local.position,
        [-257, 5120, 7680]
    );
    assert_eq!(
        world.model_position(child).unwrap(),
        Some([10.0, 20.0, 30.0]),
        "ordinary scripts must not rewrite this frame's attached presentation"
    );
    assert_eq!(
        world.spatial(child).unwrap().effective.unwrap().position,
        [2560, 5120, 7680]
    );
    world
        .refresh_automatic_models(
            &data,
            [0; 3],
            None,
            inputs,
            Some(&mut random),
            &mut |_, _| Ok(()),
        )
        .unwrap();
    assert_eq!(
        world.model_position(child).unwrap(),
        Some([-2.0, 20.0, 30.0])
    );
    assert_eq!(
        world
            .model_presentation(child)
            .unwrap()
            .unwrap()
            .pose
            .position,
        [-257, 5120, 7680]
    );
}

#[test]
fn automatic_group_release_waits_for_the_next_model_phase() {
    use cyrus_game::script::{OrdinaryInputs, ScriptInputs};
    let mut scripts = wait_cache(vec![
        wait(
            4,
            "SyncWithGroup",
            CallKind::Task,
            vec![Value::Integer { value: 3 }],
        ),
        set_flag(7),
        Operation::End { target: 0 },
    ]);
    scripts.definition.functions.push(Function {
        name: "SyncWithGroup".into(),
        param_count: 1,
        kind: CallKind::Task,
    });
    scripts
        .actors
        .get_mut("LOGIC")
        .unwrap()
        .attributes
        .insert("attr_29".into(), 5);
    for placement in &mut scripts.instances {
        placement.active = 1;
    }
    let (mut world, data, _) = static_model_fixture(scripts);
    world
        .prepare_model_admission(&Default::default(), 0)
        .unwrap();
    let inputs = ScriptInputs {
        nominal_ticks: Some(1),
        frame_scale: Some(256),
        ..Default::default()
    };
    let mut random = cyrus_game::random::EngineRandom::from_state(42);
    world
        .refresh_automatic_models(
            &data,
            [0; 3],
            None,
            inputs,
            Some(&mut random),
            &mut |_, _| Ok(()),
        )
        .unwrap();
    world
        .update_ordinary(
            &data,
            [0; 2],
            OrdinaryInputs {
                scripts: inputs,
                scene: None,
            },
            &mut random,
            &mut |_, _| Ok(()),
            100,
        )
        .unwrap();
    for index in 0..2 {
        assert_eq!(
            world.actors()[index].runtime().unwrap().active_tasks(),
            1,
            "each member must be waiting before the next family refresh"
        );
        let id = world.id(index).unwrap();
        assert!(
            world.actors()[index].failure().is_none(),
            "{:?}",
            world.actors()[index].failure()
        );
        world
            .advance(
                id,
                cyrus_game::script::ScriptStage::Tasks,
                inputs,
                None,
                None,
                100,
            )
            .unwrap();
        assert_eq!(
            world.actors()[index].runtime().unwrap().active_tasks(),
            1,
            "newly posted groups must remain unreleased during this simulation pass"
        );
    }
    world
        .refresh_automatic_models(
            &data,
            [0; 3],
            None,
            inputs,
            Some(&mut random),
            &mut |_, _| Ok(()),
        )
        .unwrap();
    for index in 0..2 {
        let id = world.id(index).unwrap();
        world
            .advance(
                id,
                cyrus_game::script::ScriptStage::Tasks,
                inputs,
                None,
                None,
                100,
            )
            .unwrap();
        assert_eq!(world.actors()[index].runtime().unwrap().active_tasks(), 0);
    }
}

#[test]
fn position_property_rejects_unavailable_owner_and_unknown_reference() {
    for (name, prepare, expected) in [
        ("pos.vx", false, "spatial owner unavailable"),
        ("unknown", true, "unsupported"),
    ] {
        let mut scripts = heading_property_scripts(294, Object::Me);
        scripts.definition.references[294] = name.into();
        scripts
            .actors
            .get_mut("LOGIC")
            .unwrap()
            .program
            .steps
            .get_mut(&0)
            .unwrap()
            .operation = Operation::Assign {
            destination: Place::Property {
                object: Object::Me,
                reference: 294,
            },
            formula: Formula {
                first: Value::Integer { value: i32::MIN },
                rest: vec![],
            },
        };
        scripts.content_id = scripts.content_identity().unwrap();
        let mut world = ScriptWorld::prepare(&scripts, 7).unwrap();
        if prepare {
            world.prepare_spatial().unwrap();
        }
        let caller = world.id(0).unwrap();
        let before = prepare.then(|| serde_json::to_value(world.spatial(caller).unwrap()).unwrap());
        let error = world
            .advance(
                caller,
                cyrus_game::script::ScriptStage::Body(Thread::Main),
                cyrus_game::script::ScriptInputs {
                    frame_scale: Some(256),
                    nominal_ticks: Some(1),
                    ..Default::default()
                },
                None,
                None,
                20,
            )
            .unwrap_err();
        assert!(format!("{error:#}").contains(expected), "{error:#}");
        if let Some(before) = before {
            assert_eq!(
                serde_json::to_value(world.spatial(caller).unwrap()).unwrap(),
                before
            );
        }
    }
}

#[test]
fn current_animation_property_reads_signed_group_without_advancing_playback() {
    use cyrus_assets::animation::Animations;
    use cyrus_game::script::{ScriptInputs, ScriptStage};
    for (group, start, expected) in [
        (None, false, 0),
        (Some(7), false, -1),
        (Some(7), true, 7),
        (Some(32768), true, -32768),
    ] {
        for (object, selected) in [
            (Object::Me, false),
            (Object::Player, true),
            (Object::Named { string: 0 }, false),
        ] {
            let mut scripts = heading_property_scripts(294, object);
            scripts.definition.references[294] = "anim.current".into();
            add_standalone_receivers(&mut scripts);
            let mut world = ScriptWorld::prepare(&scripts, 7).unwrap();
            let caller = world.id(0).unwrap();
            let receiver = world.id(if selected { 2 } else { 0 }).unwrap();
            let data = Animations {
                version: 2,
                world: scripts.world,
                metadata: serde_json::json!({"script_content_id":scripts.content_id,"actors":[{
                    "script_name":world.actors()[receiver.index].name(),
                    "animation_groups":[{"group_index":group,"anim_id":1,"anim_type":0,
                        "commands":[{"opcode":0,"frame_reference":10},{"opcode":0,"frame_reference":11},{"opcode":2,"value":0}]}]
                }]}),
                sections: Default::default(),
                models: Default::default(),
                unsupported: Default::default(),
            };
            if let Some(group) = group {
                world.bind_animation(receiver, &data, group).unwrap();
            }
            if start {
                world
                    .advance(
                        receiver,
                        ScriptStage::Animation,
                        ScriptInputs {
                            nominal_ticks: Some(1),
                            ..Default::default()
                        },
                        None,
                        None,
                        0,
                    )
                    .unwrap();
            }
            let before = world.inspect(receiver.index, 1)["actors"][0]["animation"].clone();
            world
                .advance(
                    caller,
                    ScriptStage::Body(Thread::Main),
                    ScriptInputs {
                        nominal_ticks: Some(1),
                        frame_scale: Some(256),
                        ..Default::default()
                    },
                    None,
                    None,
                    20,
                )
                .unwrap();
            assert_eq!(world.actors()[0].runtime().unwrap().variables(), [expected]);
            assert_eq!(
                world.inspect(receiver.index, 1)["actors"][0]["animation"],
                before
            );
        }
    }
}

#[test]
fn torch_property_wraps_writes_and_reads_the_shared_counter_without_other_changes() {
    use cyrus_game::script::{ScriptInputs, ScriptStage};
    for (value, expected) in [
        (-1, 255),
        (0, 0),
        (1, 1),
        (255, 255),
        (256, 0),
        (511, 255),
        (i32::MIN, 0),
        (i32::MAX, 255),
    ] {
        for (object, selected) in [
            (Object::Me, false),
            (Object::Player, true),
            (Object::Named { string: 0 }, false),
        ] {
            let mut scripts = heading_property_scripts(294, object.clone());
            scripts.definition.references[294] = "torch_timer".into();
            let program = &mut scripts.actors.get_mut("LOGIC").unwrap().program;
            let read = program.steps[&0].operation.clone();
            program.steps.insert(
                0,
                Step {
                    next: 1,
                    operation: Operation::Assign {
                        destination: Place::Property {
                            object,
                            reference: 294,
                        },
                        formula: Formula {
                            first: Value::Integer { value },
                            rest: vec![],
                        },
                    },
                },
            );
            program.steps.insert(
                1,
                Step {
                    next: 2,
                    operation: read,
                },
            );
            program.steps.insert(
                2,
                Step {
                    next: 3,
                    operation: Operation::End { target: 0 },
                },
            );
            add_standalone_receivers(&mut scripts);
            let mut world = ScriptWorld::prepare(&scripts, 7).unwrap();
            let caller = world.id(0).unwrap();
            let receiver = if selected { 2 } else { 0 };
            let other = if selected { 0 } else { 2 };
            let mut expected_control =
                serde_json::to_value(world.actors()[receiver].control_state().unwrap()).unwrap();
            expected_control["torch_burning"] = expected.into();
            let other_before =
                serde_json::to_value(world.actors()[other].control_state().unwrap()).unwrap();
            world
                .advance(
                    caller,
                    ScriptStage::Body(Thread::Main),
                    ScriptInputs {
                        nominal_ticks: Some(1),
                        frame_scale: Some(256),
                        ..Default::default()
                    },
                    None,
                    None,
                    20,
                )
                .unwrap();
            assert_eq!(world.actors()[0].runtime().unwrap().variables(), [expected]);
            assert_eq!(
                serde_json::to_value(world.actors()[receiver].control_state().unwrap()).unwrap(),
                expected_control
            );
            assert_eq!(
                serde_json::to_value(world.actors()[other].control_state().unwrap()).unwrap(),
                other_before
            );
        }
    }
}

