                    serde_json::from_value(serde_json::json!({
                "section":0,"kind":0,"animation_group":18,"min_range":minimum,"max_range":maximum,
                "first_collide_frame":0,"collide_duration":0,"arc":2048,"arc_center":0,"elevation":0
            })).unwrap()
