#[test]
fn a_shell_started_after_preparation_survives_a_snapshot_roundtrip() {
    use cyrus_game::script::{ScriptActorSource, WorldRestoreContext, WorldSnapshotSources};
    let mut scripts = cache();
    let mut shell = scripts.actors["LOGIC"].clone();
    shell.code_origin += 1000;
    shell.header_index += 100;
    scripts.actors.insert("LATER".into(), shell);
    for placement in &mut scripts.instances {
        placement.object_type = 1;
        placement.map_position = [10, 20, 30];
    }
    scripts.content_id = scripts.content_identity().unwrap();
    let (mut world, data, _) = static_model_fixture(scripts.clone());
    let census = world.actors().len();
    world.spawn_shell("LATER").unwrap();
    assert_eq!(world.actors().len(), census + 1);
    assert!(world.spawn_shell("ABSENT").is_err());
    let collision = Default::default();
    let sources = WorldSnapshotSources {
        effects: None,
        player: None,
        scripts: &scripts,
        animations: &data,
        collision: &collision,
    };
    let saved = serde_json::to_value(world.snapshot(&sources).unwrap()).unwrap();
    let restored = ScriptWorld::from_snapshot(
        serde_json::from_value(saved.clone()).unwrap(),
        &sources,
        WorldRestoreContext {
            generation: 9,
            globals: Default::default(),
            samples: &BTreeMap::new(),
        },
    )
    .unwrap();
    assert_eq!(restored.actors().len(), census + 1);
    assert!(matches!(
        &restored.actors()[census].source,
        ScriptActorSource::Shell(name) if name == "LATER"
    ));
    // Only shells may exceed the installed census.
    let mut forged = saved;
    forged["actors"][census]["source"] = serde_json::json!("map");
    assert!(
        ScriptWorld::from_snapshot(
            serde_json::from_value(forged).unwrap(),
            &sources,
            WorldRestoreContext {
                generation: 9,
                globals: Default::default(),
                samples: &BTreeMap::new(),
            },
        )
        .is_err()
    );
}

#[test]
fn open_shell_starts_the_named_script_regardless_of_case_and_rejects_unknown_names() {
    use cyrus_game::script::{ScriptInputs, ScriptStage};
    let open = |name: &str| {
        let mut scripts = cache();
        let id = u16::try_from(scripts.definition.functions.len()).unwrap();
        scripts.definition.functions.push(Function {
            name: "OpenShell".into(),
            param_count: 1,
            kind: CallKind::Function,
        });
        let mut shell = scripts.actors["LOGIC"].clone();
        shell.code_origin += 1000;
        shell.header_index += 100;
        scripts.actors.insert("ITEMLIST".into(), shell);
        let logic = scripts.actors.get_mut("LOGIC").unwrap();
        logic.program.strings = vec![name.into()];
        logic.program.steps = [
            Operation::Call {
                call: Call {
                    function_id: id,
                    function: "OpenShell".into(),
                    target: Object::Me,
                    kind: CallKind::Function,
                    arguments: vec![Value::String { index: 0 }],
                },
            },
            Operation::End { target: 0 },
        ]
        .into_iter()
        .enumerate()
        .map(|(index, operation)| {
            (
                index as u32,
                Step {
                    next: index as u32 + 1,
                    operation,
                },
            )
        })
        .collect();
        scripts.content_id = scripts.content_identity().unwrap();
        let mut world = ScriptWorld::prepare(&scripts, 1).unwrap();
        let id = world.id(0).unwrap();
        world
            .advance(
                id,
                ScriptStage::OrdinaryMain,
                ScriptInputs {
                    nominal_ticks: Some(1),
                    frame_scale: Some(256),
                    ..Default::default()
                },
                None,
                None,
                100,
            )
            .map(|()| world.running_shells("ITEMLIST"))
    };
    assert_eq!(open("itemlist").unwrap(), 1);
    assert!(open("nothing").is_err());
}

#[test]
fn a_torch_is_lit_burns_down_is_doused_and_relit_from_its_saved_counter() {
    use cyrus_game::script::{ScriptInputs, ScriptStage};
    let (_, mut world, _, _) = player_walking_fixture_with(|scripts| {
        let id = u16::try_from(scripts.definition.functions.len()).unwrap();
        scripts.definition.functions.push(Function {
            name: "UseItem".into(),
            param_count: 1,
            kind: CallKind::Function,
        });
        let call = Operation::ObjectCall {
            call: Call {
                function_id: id,
                function: "UseItem".into(),
                target: Object::Player,
                kind: CallKind::Function,
                arguments: vec![Value::Integer { value: 45 }],
            },
        };
        scripts.actors.get_mut("LOGIC").unwrap().program.steps =
            [call, Operation::End { target: 0 }]
                .into_iter()
                .enumerate()
                .map(|(index, operation)| {
                    (
                        index as u32,
                        Step {
                            next: index as u32 + 1,
                            operation,
                        },
                    )
                })
                .collect();
    });
    let hud = cyrus_game::script::ScriptHud::default();
    let mut asset = inventory_asset(&[(45, 1)]);
    asset.inventory.get_mut(&45).unwrap().item_type = 3;
    asset.torch_time = Some(60);
    hud.configure(&asset, &cyrus_game::preferences::Preferences::default());
    let map = world.id(0).unwrap();
    let player = world
        .id(world
            .actors()
            .iter()
            .position(|actor| matches!(actor.source, cyrus_game::script::ScriptActorSource::Player))
            .unwrap())
        .unwrap();
    let inputs = || ScriptInputs {
        hud: Some(&hud),
        shell_execution: Some(false),
        nominal_ticks: Some(2),
        frame_scale: Some(256),
        ..Default::default()
    };
    let torch = |world: &ScriptWorld| {
        let control = world.actors()[player.index].control_state().unwrap();
        (
            control.living_state,
            control.torch_burning,
            control.torch_saved,
        )
    };
    let use_item = |world: &mut ScriptWorld| {
        world.globals_mut().end_item_use_attempt();
        world
            .advance(
                map,
                ScriptStage::OrdinaryMain,
                inputs(),
                Some(&mut |_, _| Ok(())),
                None,
                100,
            )
            .unwrap();
    };
    let progress = |world: &mut ScriptWorld| {
        for _ in 0..4 {
            world.run_held_torch(player, inputs(), 2, &mut |_, _| Ok(()));
            world
                .advance(
                    player,
                    ScriptStage::Animation,
                    inputs(),
                    Some(&mut |_, _| Ok(())),
                    None,
                    100,
                )
                .unwrap();
        }
        assert!(
            world.actors()[player.index].failure().is_none(),
            "{:?}",
            world.actors()[player.index].failure()
        );
    };
    use_item(&mut world);
    assert_eq!(torch(&world), (33, 0, 0), "lighting begins");
    progress(&mut world);
    assert_eq!(
        torch(&world),
        (0, 90, 90),
        "sixty seconds burn for ninety counts"
    );
    world
        .advance_torch_burn(player, inputs(), 2, &mut |_, _| Ok(()))
        .unwrap();
    assert_eq!(torch(&world).1, 88, "the countdown loses the nominal ticks");
    use_item(&mut world);
    assert_eq!(
        torch(&world).0,
        34,
        "any use while burning puts the torch out"
    );
    progress(&mut world);
    assert_eq!(
        torch(&world),
        (0, 0, 88),
        "the counter is saved when doused"
    );
    use_item(&mut world);
    progress(&mut world);
    assert_eq!(
        torch(&world),
        (0, 88, 88),
        "relighting restores the saved counter"
    );
}

#[test]
fn light_torch_starts_the_lighting_state_and_unlight_torch_waits_for_a_burning_torch() {
    use cyrus_game::script::{ScriptInputs, ScriptStage};
    let (_, mut world, _, _) = player_walking_fixture_with(|scripts| {
        let mut call = |name: &str| {
            let id = u16::try_from(scripts.definition.functions.len()).unwrap();
            scripts.definition.functions.push(Function {
                name: name.into(),
                param_count: 0,
                kind: CallKind::Function,
            });
            Operation::ObjectCall {
                call: Call {
                    function_id: id,
                    function: name.into(),
                    target: Object::Player,
                    kind: CallKind::Function,
                    arguments: vec![],
                },
            }
        };
        // The first update lights the torch and parks the continuation on the dousing call.
        let steps = [
            call("LightTorch"),
            Operation::End { target: 2 },
            call("UnlightTorch"),
            Operation::End { target: 2 },
        ];
        scripts.actors.get_mut("LOGIC").unwrap().program.steps = steps
            .into_iter()
            .enumerate()
            .map(|(index, operation)| {
                (
                    index as u32,
                    Step {
                        next: index as u32 + 1,
                        operation,
                    },
                )
            })
            .collect();
    });
    let hud = cyrus_game::script::ScriptHud::default();
    let mut asset = inventory_asset(&[(45, 1)]);
    asset.inventory.get_mut(&45).unwrap().item_type = 3;
    asset.torch_time = Some(60);
    hud.configure(&asset, &cyrus_game::preferences::Preferences::default());
    let map = world.id(0).unwrap();
    let player = world
        .id(world
            .actors()
            .iter()
            .position(|actor| matches!(actor.source, cyrus_game::script::ScriptActorSource::Player))
            .unwrap())
        .unwrap();
    let inputs = || ScriptInputs {
        hud: Some(&hud),
        shell_execution: Some(false),
        nominal_ticks: Some(2),
        frame_scale: Some(256),
        ..Default::default()
    };
    let torch = |world: &ScriptWorld| {
        let control = world.actors()[player.index].control_state().unwrap();
        (control.living_state, control.torch_burning)
    };
    let run = |world: &mut ScriptWorld| {
        world
            .advance(
                map,
                ScriptStage::OrdinaryMain,
                inputs(),
                Some(&mut |_, _| Ok(())),
                None,
                100,
            )
            .unwrap();
        assert!(world.actors()[map.index].failure().is_none());
    };
    run(&mut world);
    assert_eq!(
        torch(&world),
        (33, 0),
        "LightTorch begins the lighting state"
    );
    // The torch is still lighting: dousing is not admitted, so UnlightTorch completes and changes nothing.
    run(&mut world);
    assert_eq!(
        torch(&world),
        (33, 0),
        "UnlightTorch leaves a lighting torch alone"
    );
}

#[test]
fn draw_sword_enters_the_draw_state_and_a_weapon_item_use_draws_it() {
    use cyrus_game::script::{ScriptInputs, ScriptStage};
    for item_use in [false, true] {
        let (_, mut world, _, _) = player_walking_fixture_with(|scripts| {
            let name = if item_use { "UseItem" } else { "DrawSword" };
            let id = u16::try_from(scripts.definition.functions.len()).unwrap();
            scripts.definition.functions.push(Function {
                name: name.into(),
                param_count: u8::from(item_use),
                kind: CallKind::Function,
            });
            let call = Operation::ObjectCall {
                call: Call {
                    function_id: id,
                    function: name.into(),
                    target: Object::Player,
                    kind: CallKind::Function,
                    arguments: if item_use {
                        vec![Value::Integer { value: 1 }]
                    } else {
                        vec![]
                    },
                },
            };
            scripts.actors.get_mut("LOGIC").unwrap().program.steps =
                [call, Operation::End { target: 0 }]
                    .into_iter()
                    .enumerate()
                    .map(|(index, operation)| {
                        (
                            index as u32,
                            Step {
                                next: index as u32 + 1,
                                operation,
                            },
                        )
                    })
                    .collect();
        });
        let hud = cyrus_game::script::ScriptHud::default();
        let mut asset = inventory_asset(&[(1, 1)]);
        asset.inventory.get_mut(&1).unwrap().item_type = 1;
        asset.inventory.get_mut(&1).unwrap().weapon = true;
        hud.configure(&asset, &cyrus_game::preferences::Preferences::default());
        let map = world.id(0).unwrap();
        let player = world
            .id(world
                .actors()
                .iter()
                .position(|actor| {
                    matches!(actor.source, cyrus_game::script::ScriptActorSource::Player)
                })
                .unwrap())
            .unwrap();
        world
            .advance(
                map,
                ScriptStage::OrdinaryMain,
                ScriptInputs {
                    hud: Some(&hud),
                    shell_execution: Some(false),
                    nominal_ticks: Some(1),
                    frame_scale: Some(256),
                    ..Default::default()
                },
                Some(&mut |_, _| Ok(())),
                None,
                100,
            )
            .unwrap();
        let actor = &world.actors()[player.index];
        let control = actor.control_state().unwrap();
        assert_eq!(control.living_state, 20, "item use: {item_use}");
        assert_eq!(control.combat.as_ref().unwrap().flags & 4, 4);
        if item_use {
            assert_eq!(actor.attributes()[23], 1, "the item becomes the weapon");
        }
    }
}

#[test]
fn sheath_sword_and_end_combat_dispatch_to_the_combat_services() {
    use cyrus_game::script::{ScriptInputs, ScriptStage};
    // An unarmed player cannot sheathe, so SheathSword completes without a state change; endCombat
    // still runs its unconditional reset of the lifecycle selector, AI mode and combat flag.
    for function in ["SheathSword", "endCombat"] {
        let (_, mut world, _, _) = player_walking_fixture_with(|scripts| {
            let id = u16::try_from(scripts.definition.functions.len()).unwrap();
            scripts.definition.functions.push(Function {
                name: function.into(),
                param_count: 0,
                kind: CallKind::Function,
            });
            let call = Operation::ObjectCall {
                call: Call {
                    function_id: id,
                    function: function.into(),
                    target: Object::Player,
                    kind: CallKind::Function,
                    arguments: vec![],
                },
            };
            scripts.actors.get_mut("LOGIC").unwrap().program.steps =
                [call, Operation::End { target: 0 }]
                    .into_iter()
                    .enumerate()
                    .map(|(index, operation)| {
                        (
                            index as u32,
                            Step {
                                next: index as u32 + 1,
                                operation,
                            },
                        )
                    })
                    .collect();
        });
        let hud = cyrus_game::script::ScriptHud::default();
        hud.configure(
            &inventory_asset(&[]),
            &cyrus_game::preferences::Preferences::default(),
        );
        let map = world.id(0).unwrap();
        let player = world
            .id(world
                .actors()
                .iter()
                .position(|actor| {
                    matches!(actor.source, cyrus_game::script::ScriptActorSource::Player)
                })
                .unwrap())
            .unwrap();
        let before = world.actors()[player.index]
            .control_state()
            .unwrap()
            .death_selector;
        world
            .advance(
                map,
                ScriptStage::OrdinaryMain,
                ScriptInputs {
                    hud: Some(&hud),
                    shell_execution: Some(false),
                    nominal_ticks: Some(1),
                    frame_scale: Some(256),
                    ..Default::default()
                },
                Some(&mut |_, _| Ok(())),
                None,
                100,
            )
            .unwrap();
        assert!(world.actors()[map.index].failure().is_none(), "{function}");
        let control = world.actors()[player.index].control_state().unwrap();
        assert_eq!(
            control.living_state, 0,
            "{function} leaves an unarmed player idle"
        );
        if function == "endCombat" {
            assert_eq!(control.death_selector, 1);
            assert_eq!(control.death_response, 0);
            assert_eq!(control.combat.as_ref().unwrap().flags & 4, 0);
        } else {
            assert_eq!(
                control.death_selector, before,
                "SheathSword leaves the selector"
            );
        }
    }
}

#[test]
fn player_collide_natives_read_the_selected_players_contact_lists() {
    use cyrus_game::script::{ScriptInputs, ScriptStage};
    let run = |function: &str, touched: Option<usize>| {
        let (_, mut world, _, _) = player_walking_fixture_with(|scripts| {
            let id = u16::try_from(scripts.definition.functions.len()).unwrap();
            scripts.definition.functions.push(Function {
                name: function.into(),
                param_count: 0,
                kind: CallKind::Function,
            });
            scripts.actors.get_mut("LOGIC").unwrap().program.steps = [
                assign_call(1, id, function, &[]).operation,
                set_flag(7),
                Operation::End { target: 0 },
            ]
            .into_iter()
            .enumerate()
            .map(|(index, operation)| {
                (
                    index as u32,
                    Step {
                        next: index as u32 + 1,
                        operation,
                    },
                )
            })
            .collect();
        });
        if let Some(actor) = touched {
            world.globals_mut().record_player_contact(actor);
        }
        let map = world.id(0).unwrap();
        world
            .advance(
                map,
                ScriptStage::OrdinaryMain,
                ScriptInputs {
                    nominal_ticks: Some(1),
                    frame_scale: Some(256),
                    ..Default::default()
                },
                Some(&mut |_, _| Ok(())),
                None,
                100,
            )
            .unwrap();
        world.actors()[0].runtime().unwrap().variables()[0]
    };
    for function in ["PlayerCollide", "PlayerCollideStatic"] {
        assert_eq!(run(function, None), 0, "{function} without contact");
        assert_eq!(
            run(function, Some(0)),
            1,
            "{function} touching the receiver"
        );
        assert_eq!(
            run(function, Some(1)),
            0,
            "{function} touching another actor"
        );
    }
}

