#[test]
fn add_flat_effect_retains_native_speed_and_rejects_nonzero_spread() {
    use cyrus_assets::effects::{EffectImage, Effects};
    let mut effects = Effects {
        ambient_brightness: Some(128),
        capacity: 2,
        disabled: false,
        images: BTreeMap::from([(
            0x2380,
            EffectImage {
                name: "brazier".into(),
                size: [1, 4],
                texture_scale: 256,
                delay_ms: 71,
                flags: 1,
                alpha: 151,
                frames: vec![vec![255; 16]; 4],
            },
        )]),
    };
    effects.images.insert(0, effects.images[&0x2380].clone());
    let spawn = |spread: i32, speed: i32, descriptor: i32| {
        let mut world = {
            let mut scripts = random_scripts("Rnd", vec![], Object::Me);
            scripts.definition.functions.push(Function {
                name: "AddFlatEffect".into(),
                param_count: 6,
                kind: CallKind::Function,
            });
            let id = u16::try_from(scripts.definition.functions.len() - 1).unwrap();
            scripts.actors.get_mut("LOGIC").unwrap().program.steps = [
                assign_call(
                    1,
                    id,
                    "AddFlatEffect",
                    &[2560, 5120, 7680, spread, descriptor, speed],
                )
                .operation,
                Operation::End { target: 0 },
            ]
            .into_iter()
            .enumerate()
            .map(|(index, operation)| {
                (
                    index as u32,
                    Step {
                        next: index as u32 + 1,
                        operation,
                    },
                )
            })
            .collect();
            scripts.content_id = scripts.content_identity().unwrap();
            ScriptWorld::prepare(&scripts, 1).unwrap()
        };
        world.prepare_environment_effects(&effects).unwrap();
        let id = world.id(0).unwrap();
        world
            .advance(
                id,
                cyrus_game::script::ScriptStage::OrdinaryMain,
                cyrus_game::script::ScriptInputs {
                    frame_scale: Some(256),
                    nominal_ticks: Some(1),
                    ..Default::default()
                },
                None,
                None,
                100,
            )
            .map(|()| world.actors()[0].failure().map(str::to_owned))
            .map(|failure| {
                let count = world
                    .environmental_effects()
                    .map_or(0, |effects| effects.active().count());
                world.advance_environment_effects(1);
                let frame = world
                    .environmental_effects()
                    .unwrap()
                    .active()
                    .next()
                    .map(|(_, effect)| effect.frame);
                (failure, count, frame)
            })
    };
    for speed in [1, 2] {
        let (failure, count, frame) = spawn(0, speed, 0x2380).unwrap();
        assert!(failure.is_none(), "{failure:?}");
        assert_eq!(count, 1);
        assert_eq!(frame, Some(speed));
    }
    for descriptor in [0, 0x20000] {
        let (failure, count, frame) = spawn(0, 3, descriptor).unwrap();
        assert!(failure.is_none(), "{failure:?}");
        assert_eq!(count, 1);
        assert_eq!(frame, Some(0));
    }
    let error = spawn(5, 1, 0x2380).unwrap_err();
    assert!(format!("{error:#}").contains("nonzero spread unsupported"));
}

/// A living receiver with a combat record, running `DragonBreath` once with the given combat flags.
fn dragon_breath_once(flags: u8) -> (anyhow::Result<i32>, usize, f64) {
    use cyrus_game::script::{ScriptInputs, ScriptStage};
    let (mut world, _, _) = movement_fixture(
        18,
        false,
        true,
        |scripts| {
            let id = u16::try_from(scripts.definition.functions.len()).unwrap();
            scripts.definition.functions.push(Function {
                name: "DragonBreath".into(),
                param_count: 0,
                kind: CallKind::Function,
            });
            scripts.actors.get_mut("LOGIC").unwrap().program.steps = [
                assign_call(1, id, "DragonBreath", &[]).operation,
                Operation::End { target: 0 },
            ]
            .into_iter()
            .enumerate()
            .map(|(index, operation)| {
                (
                    index as u32,
                    Step {
                        next: index as u32 + 1,
                        operation,
                    },
                )
            })
            .collect();
        },
        |saved| {
            for index in 0..2 {
                saved["actors"][index]["control"]["combat"] =
                    serde_json::to_value(cyrus_game::script::CombatControlState::default())
                        .unwrap();
                saved["actors"][index]["control"]["combat"]["flags"] = flags.into();
            }
            saved["actors"][0]["control"]["combat"]["target"] = serde_json::json!([1, 1]);
        },
    );
    let dragon = world.id(0).unwrap();
    let census = world.actors().len();
    let [a, b] = [0, 1].map(|index| {
        world
            .spatial(world.id(index).unwrap())
            .unwrap()
            .local
            .position
    });
    let distance = (0..3)
        .map(|axis| f64::from(a[axis].wrapping_sub(b[axis])).powi(2))
        .sum::<f64>()
        .sqrt();
    let result = world
        .advance(
            dragon,
            ScriptStage::OrdinaryMain,
            ScriptInputs {
                nominal_ticks: Some(1),
                frame_scale: Some(256),
                ..Default::default()
            },
            Some(&mut |_, _| Ok(())),
            Some(&mut cyrus_game::random::EngineRandom::from_state(1)),
            100,
        )
        .map(|_| world.actors()[0].runtime().unwrap().variables()[0]);
    (result, world.actors().len() - census, distance)
}

#[test]
fn a_living_dragon_without_the_targeting_flag_keeps_breathing_and_creates_nothing() {
    let (result, created, _) = dragon_breath_once(0);
    assert_eq!((result.unwrap(), created), (1, 0));
}

#[test]
fn a_dragon_closer_than_its_minimum_range_to_its_target_keeps_breathing_without_fire() {
    let (result, created, distance) = dragon_breath_once(4);
    assert!(distance < f64::from(0x19000), "fixture distance {distance}");
    assert_eq!((result.unwrap(), created), (1, 0));
}

#[test]
fn a_dead_dragon_swaps_the_taken_item_for_the_given_one_and_returns_zero() {
    use cyrus_game::script::{ScriptActorSource, ScriptInputs, ScriptStage};
    let (_, mut world, _, _) = player_walking_fixture_with(|scripts| {
        let mut steps = Vec::new();
        for name in ["KillMe", "DragonBreath"] {
            let id = u16::try_from(scripts.definition.functions.len()).unwrap();
            scripts.definition.functions.push(Function {
                name: name.into(),
                param_count: 0,
                kind: CallKind::Function,
            });
            steps.push(assign_call(steps.len() as u32 + 1, id, name, &[]).operation);
        }
        steps.push(Operation::End { target: 0 });
        scripts.actors.get_mut("LOGIC").unwrap().program.steps = steps
            .into_iter()
            .enumerate()
            .map(|(index, operation)| {
                (
                    index as u32,
                    Step {
                        next: index as u32 + 1,
                        operation,
                    },
                )
            })
            .collect();
    });
    let hud = cyrus_game::script::ScriptHud::default();
    hud.configure(
        &inventory_asset(&[(0x4b, 1), (1, 0)]),
        &cyrus_game::preferences::Preferences::default(),
    );
    let dragon = world.id(0).unwrap();
    world
        .advance(
            dragon,
            ScriptStage::OrdinaryMain,
            ScriptInputs {
                hud: Some(&hud),
                nominal_ticks: Some(1),
                frame_scale: Some(256),
                ..Default::default()
            },
            Some(&mut |_, _| Ok(())),
            Some(&mut cyrus_game::random::EngineRandom::default()),
            100,
        )
        .unwrap();
    assert_eq!(world.actors()[0].runtime().unwrap().variables()[0], 0);
    let counts = hud.inventory(None).unwrap().counts;
    assert_eq!((counts[&0x4b], counts[&1]), (0, 1));
    assert_eq!(hud.active_item().unwrap(), 1);
    let player = world
        .actors()
        .iter()
        .position(|actor| matches!(actor.source, ScriptActorSource::Player))
        .unwrap();
    assert_eq!(world.actors()[player].attributes()[23], 1);
}

#[test]
fn golem_steam_acts_on_one_draw_in_four_and_needs_animation_data_then() {
    use cyrus_game::random::EngineRandom;
    let run = |state: u32| {
        let mut scripts = random_scripts("Rnd", vec![], Object::Me);
        scripts.definition.functions.push(Function {
            name: "GolemSteam".into(),
            param_count: 0,
            kind: CallKind::Function,
        });
        let id = u16::try_from(scripts.definition.functions.len() - 1).unwrap();
        scripts.actors.get_mut("LOGIC").unwrap().program.steps = [
            assign_call(1, id, "GolemSteam", &[]).operation,
            Operation::End { target: 0 },
        ]
        .into_iter()
        .enumerate()
        .map(|(index, operation)| {
            (
                index as u32,
                Step {
                    next: index as u32 + 1,
                    operation,
                },
            )
        })
        .collect();
        scripts.content_id = scripts.content_identity().unwrap();
        let mut world = ScriptWorld::prepare(&scripts, 1).unwrap();
        let mut random = EngineRandom::from_state(state);
        let actor = world.id(0).unwrap();
        world.advance(
            actor,
            cyrus_game::script::ScriptStage::OrdinaryMain,
            cyrus_game::script::ScriptInputs {
                frame_scale: Some(256),
                nominal_ticks: Some(1),
                ..Default::default()
            },
            None,
            Some(&mut random),
            100,
        )
    };
    let first_draw_acts = |state: u32| EngineRandom::from_state(state).rnd(4).unwrap() == 0;
    let acting = (0..64).find(|state| first_draw_acts(*state)).unwrap();
    let idle = (0..64).find(|state| !first_draw_acts(*state)).unwrap();
    run(idle).unwrap();
    let error = run(acting).unwrap_err();
    assert!(
        format!("{error:#}").contains("animation data unavailable"),
        "{error:#}"
    );
}

#[test]
fn a_created_object_takes_its_creators_frame_runs_each_update_and_survives_a_snapshot() {
    use cyrus_game::script::{
        ScriptActorSource, ScriptInputs, WorldRestoreContext, WorldSnapshotSources,
    };
    let mut scripts = cache();
    let mut projectile = scripts.actors["LOGIC"].clone();
    projectile.code_origin += 1000;
    projectile.header_index += 100;
    projectile
        .attributes
        .insert("attr_forward_speed".into(), 50);
    scripts.actors.insert("BALL".into(), projectile);
    for placement in &mut scripts.instances {
        placement.object_type = 1;
        placement.map_position = [10, 20, 30];
    }
    scripts.content_id = scripts.content_identity().unwrap();
    let (mut world, data, _) = static_model_fixture(scripts.clone());
    let census = world.actors().len();
    let creator = world.id(0).unwrap();
    let created = world
        .create_object(creator, "ball", [0, 0, 256], [0, 512, 0])
        .unwrap();
    assert_eq!(world.actors().len(), census + 1);
    assert!(matches!(
        &world.actors()[created.index].source,
        ScriptActorSource::Created(name) if name == "BALL"
    ));
    assert_eq!(world.actors()[created.index].attributes()[0], 0);
    assert!(
        world
            .create_object(creator, "absent", [0; 3], [0; 3])
            .is_err()
    );
    let at = world.spatial(created).unwrap().local.position;
    let origin = world.spatial(creator).unwrap().local.position;
    assert_ne!(at, origin, "the offset moved it off its creator");
    world
        .update_created(
            ScriptInputs {
                nominal_ticks: Some(1),
                frame_scale: Some(256),
                ..Default::default()
            },
            &mut cyrus_game::random::EngineRandom::default(),
            &mut |_, _| Ok(()),
            100,
        )
        .unwrap();
    assert!(world.actors()[created.index].failure().is_none());
    let collision = Default::default();
    let sources = WorldSnapshotSources {
        effects: None,
        player: None,
        scripts: &scripts,
        animations: &data,
        collision: &collision,
    };
    let saved = serde_json::to_value(world.snapshot(&sources).unwrap()).unwrap();
    let restored = ScriptWorld::from_snapshot(
        serde_json::from_value(saved).unwrap(),
        &sources,
        WorldRestoreContext {
            generation: 9,
            globals: Default::default(),
            samples: &BTreeMap::new(),
        },
    )
    .unwrap();
    assert_eq!(restored.actors().len(), census + 1);
    let id = restored.id(created.index).unwrap();
    assert_eq!(restored.spatial(id).unwrap().local.position, at);
}

#[test]
fn a_created_object_snapshot_rejects_an_out_of_range_creator_reference() {
    use cyrus_game::script::{ScriptActorSource, WorldRestoreContext, WorldSnapshotSources};
    let mut scripts = cache();
    let mut projectile = scripts.actors["LOGIC"].clone();
    projectile.code_origin += 1000;
    projectile.header_index += 100;
    scripts.actors.insert("BALL".into(), projectile);
    for placement in &mut scripts.instances {
        placement.object_type = 1;
        placement.map_position = [10, 20, 30];
    }
    scripts.content_id = scripts.content_identity().unwrap();
    let (mut world, data, _) = static_model_fixture(scripts.clone());
    let creator = world.id(0).unwrap();
    let created = world
        .create_object(creator, "ball", [0, 0, 256], [0, 0, 0])
        .unwrap();
    assert!(matches!(
        &world.actors()[created.index].source,
        ScriptActorSource::Created(name) if name == "BALL"
    ));
    let collision = Default::default();
    let sources = WorldSnapshotSources {
        effects: None,
        player: None,
        scripts: &scripts,
        animations: &data,
        collision: &collision,
    };
    let mut saved = serde_json::to_value(world.snapshot(&sources).unwrap()).unwrap();
    saved["actors"][created.index]["control"]["creator"] = serde_json::json!(9999);
    let result = ScriptWorld::from_snapshot(
        serde_json::from_value(saved).unwrap(),
        &sources,
        WorldRestoreContext {
            generation: 9,
            globals: Default::default(),
            samples: &BTreeMap::new(),
        },
    );
    let error = match result {
        Ok(_) => panic!("restore accepted an out-of-range creator"),
        Err(error) => error,
    };
    assert!(
        format!("{error:#}").contains("saved creator actor 9999 is stale or absent"),
        "{error:#}"
    );
}

#[test]
fn shoot_creates_the_named_object_at_the_creator_with_the_given_orientation() {
    use cyrus_game::script::{ScriptActorSource, ScriptInputs, ScriptStage};
    let shoot = |name_known: bool| {
        let mut scripts = cache();
        let mut projectile = scripts.actors["LOGIC"].clone();
        projectile.code_origin += 1000;
        projectile.header_index += 100;
        scripts.actors.insert("BALL".into(), projectile);
        let id = u16::try_from(scripts.definition.functions.len()).unwrap();
        scripts.definition.functions.push(Function {
            name: "shoot".into(),
            param_count: 7,
            kind: CallKind::Function,
        });
        let logic = scripts.actors.get_mut("LOGIC").unwrap();
        logic.program.strings = vec![if name_known { "ball" } else { "nothing" }.into()];
        let mut arguments = vec![Value::String { index: 0 }];
        arguments.extend([0, 0, 0, 0, 512, 0].map(|value| Value::Integer { value }));
        logic.program.steps = [
            Operation::Call {
                call: Call {
                    function_id: id,
                    function: "shoot".into(),
                    target: Object::Me,
                    kind: CallKind::Function,
                    arguments,
                },
            },
            Operation::End { target: 0 },
        ]
        .into_iter()
        .enumerate()
        .map(|(index, operation)| {
            (
                index as u32,
                Step {
                    next: index as u32 + 1,
                    operation,
                },
            )
        })
        .collect();
        for placement in &mut scripts.instances {
            placement.map_position = [10, 20, 30];
        }
        scripts.content_id = scripts.content_identity().unwrap();
        let mut world = ScriptWorld::prepare(&scripts, 1).unwrap();
        world.prepare_spatial().unwrap();
        let creator = world.id(0).unwrap();
        world
            .advance(
                creator,
                ScriptStage::OrdinaryMain,
                ScriptInputs {
                    nominal_ticks: Some(1),
                    frame_scale: Some(256),
                    ..Default::default()
                },
                None,
                None,
                100,
            )
            .map(|()| world)
    };
    let world = shoot(true).unwrap();
    let created = world
        .actors()
        .iter()
        .position(
            |actor| matches!(&actor.source, ScriptActorSource::Created(name) if name == "BALL"),
        )
        .expect("the object exists");
    let id = world.id(created).unwrap();
    let pose = world.spatial(id).unwrap().local;
    assert_eq!(pose.angles, [0, 512, 0]);
    let creator = world.spatial(world.id(0).unwrap()).unwrap().local.position;
    assert_eq!(
        pose.position, creator,
        "a zero offset puts the object on its creator"
    );
    assert!(shoot(false).is_err(), "an unknown script name is an error");
}

#[test]
fn shoot_player_aims_the_created_object_at_the_selected_player() {
    use cyrus_game::script::{ScriptActorSource, ScriptInputs, ScriptStage};
    let (_, mut world, _, _) = player_walking_fixture_with(|scripts| {
        let mut projectile = scripts.actors["LOGIC"].clone();
        projectile.code_origin += 1000;
        projectile.header_index += 100;
        scripts.actors.insert("BALL".into(), projectile);
        let id = u16::try_from(scripts.definition.functions.len()).unwrap();
        scripts.definition.functions.push(Function {
            name: "shootPlayer".into(),
            param_count: 4,
            kind: CallKind::Function,
        });
        let logic = scripts.actors.get_mut("LOGIC").unwrap();
        logic.program.strings = vec!["ball".into()];
        logic.program.steps = [
            Operation::Call {
                call: Call {
                    function_id: id,
                    function: "shootPlayer".into(),
                    target: Object::Me,
                    kind: CallKind::Function,
                    arguments: vec![
                        Value::String { index: 0 },
                        Value::Integer { value: 0 },
                        Value::Integer { value: 0 },
                        Value::Integer { value: 256 },
                    ],
                },
            },
            Operation::End { target: 0 },
        ]
        .into_iter()
        .enumerate()
        .map(|(index, operation)| {
            (
                index as u32,
                Step {
                    next: index as u32 + 1,
                    operation,
                },
            )
        })
        .collect();
    });
    let map = world.id(0).unwrap();
    world
        .advance(
            map,
            ScriptStage::OrdinaryMain,
            ScriptInputs {
                nominal_ticks: Some(1),
                frame_scale: Some(256),
                ..Default::default()
            },
            None,
            None,
            100,
        )
        .unwrap();
    let created = world
        .actors()
        .iter()
        .position(|actor| matches!(actor.source, ScriptActorSource::Created(_)))
        .expect("the object exists");
    let pose = world.spatial(world.id(created).unwrap()).unwrap().local;
    let player = world
        .actors()
        .iter()
        .position(|actor| matches!(actor.source, ScriptActorSource::Player))
        .unwrap();
    let target = world
        .spatial(world.id(player).unwrap())
        .unwrap()
        .local
        .position;
    let (dx, dz) = (
        f64::from(target[0].wrapping_sub(pose.position[0])),
        f64::from(target[2].wrapping_sub(pose.position[2])),
    );
    assert!(
        dx != 0.0 || dz != 0.0,
        "the fixture separates the player from the shot"
    );
    let expected = (-dx.atan2(dz) * 2048.0 / std::f64::consts::TAU).rem_euclid(2048.0);
    let yaw = f64::from(pose.angles[1]);
    let distance = (yaw - expected).abs().min(2048.0 - (yaw - expected).abs());
    assert!(distance <= 2.0, "yaw {yaw} against {expected}");
    assert_eq!(pose.angles[2], 0, "roll is zero");
}

#[test]
fn a_direct_damage_message_hurts_the_selected_player_through_shared_health() {
    use cyrus_game::script::{ScriptActorSource, ScriptHud, ScriptInputs};
    let (_, mut world, _, _) = player_health_fixture();
    let receiver = world.selected_player().unwrap();
    let sender = (0..world.actors().len())
        .map(|index| world.id(index).unwrap())
        .find(|id| {
            *id != receiver && !matches!(world.actors()[id.index].source, ScriptActorSource::Player)
        })
        .unwrap();
    world.ordinary_actors([0, 0]).unwrap();
    world.set_attribute_for_test(sender, 96, 12);
    let before = world.spatial(receiver).unwrap().local.position;
    world.send_combat_message(sender, receiver, 0xd005).unwrap();
    let hud = ScriptHud::default();
    world
        .process_combat_message_with_services(
            receiver,
            None,
            ScriptInputs {
                hud: Some(&hud),
                death_suppressed: Some(false),
                nominal_ticks: Some(1),
                frame_scale: Some(256),
                ..Default::default()
            },
            Some(&mut cyrus_game::random::EngineRandom::from_state(42)),
            &mut |_, _| Ok(()),
        )
        .unwrap();
    assert_eq!(world.consume_combat_message(receiver).unwrap(), None);
    assert_ne!(world.spatial(receiver).unwrap().local.position, before);
    assert_eq!(world.globals().selected_health().unwrap().displayed(), 38);
    assert_eq!(
        world.actors()[receiver.index]
            .control_state()
            .unwrap()
            .combat
            .as_ref()
            .unwrap()
            .attacker_selection_state,
        0,
        "direct damage does not hand coordination to the selected player"
    );
}

